-- Hospital Directory owns department identity. Queue must use the same UUIDs
-- when consuming AppointmentConfirmed events. The composite FK temporarily
-- prevents changing the parent and child keys in separate statements.
ALTER TABLE queue.queue_entries DROP CONSTRAINT IF EXISTS fk_queue_entry_config_context;
UPDATE queue.queue_configs
SET department_id = CASE department_id
    WHEN '10000000-0000-0000-0000-000000000001' THEN 'de000001-0000-0000-0000-000000000001'::uuid
    WHEN '10000000-0000-0000-0000-000000000002' THEN 'de000001-0000-0000-0000-000000000002'::uuid
    WHEN '10000000-0000-0000-0000-000000000003' THEN 'de000001-0000-0000-0000-000000000003'::uuid
    WHEN '10000000-0000-0000-0000-000000000004' THEN 'de000001-0000-0000-0000-000000000004'::uuid
    WHEN '10000000-0000-0000-0000-000000000005' THEN 'de000001-0000-0000-0000-000000000005'::uuid
    WHEN '10000000-0000-0000-0000-000000000006' THEN 'de000001-0000-0000-0000-000000000006'::uuid
    WHEN '10000000-0000-0000-0000-000000000007' THEN 'de000001-0000-0000-0000-000000000007'::uuid
    WHEN '10000000-0000-0000-0000-000000000008' THEN 'de000001-0000-0000-0000-000000000008'::uuid
    WHEN '10000000-0000-0000-0000-000000000009' THEN 'de000001-0000-0000-0000-000000000009'::uuid
    WHEN '10000000-0000-0000-0000-000000000010' THEN 'de000001-0000-0000-0000-000000000010'::uuid
    WHEN '10000000-0000-0000-0000-000000000011' THEN 'de000001-0000-0000-0000-000000000011'::uuid
    ELSE department_id
END
WHERE department_id::text LIKE '10000000-%';

UPDATE queue.queue_entries
SET department_id = CASE department_id
    WHEN '10000000-0000-0000-0000-000000000001' THEN 'de000001-0000-0000-0000-000000000001'::uuid
    WHEN '10000000-0000-0000-0000-000000000002' THEN 'de000001-0000-0000-0000-000000000002'::uuid
    WHEN '10000000-0000-0000-0000-000000000003' THEN 'de000001-0000-0000-0000-000000000003'::uuid
    WHEN '10000000-0000-0000-0000-000000000004' THEN 'de000001-0000-0000-0000-000000000004'::uuid
    WHEN '10000000-0000-0000-0000-000000000005' THEN 'de000001-0000-0000-0000-000000000005'::uuid
    WHEN '10000000-0000-0000-0000-000000000006' THEN 'de000001-0000-0000-0000-000000000006'::uuid
    WHEN '10000000-0000-0000-0000-000000000007' THEN 'de000001-0000-0000-0000-000000000007'::uuid
    WHEN '10000000-0000-0000-0000-000000000008' THEN 'de000001-0000-0000-0000-000000000008'::uuid
    WHEN '10000000-0000-0000-0000-000000000009' THEN 'de000001-0000-0000-0000-000000000009'::uuid
    WHEN '10000000-0000-0000-0000-000000000010' THEN 'de000001-0000-0000-0000-000000000010'::uuid
    WHEN '10000000-0000-0000-0000-000000000011' THEN 'de000001-0000-0000-0000-000000000011'::uuid
    ELSE department_id
END
WHERE department_id::text LIKE '10000000-%';

ALTER TABLE queue.queue_entries
    ADD CONSTRAINT fk_queue_entry_config_context FOREIGN KEY (queue_config_id, department_id)
        REFERENCES queue.queue_configs(id, department_id);
